1	import { spawn, ChildProcess } from "node:child_process";
2	import * as path from "node:path";
3	import * as fs from "node:fs";
4	import * as os from "node:os";
5	import { pathToFileURL, fileURLToPath } from "node:url";
6	import { buildMcpEnvironment } from "./mcp.js";
7	
8	const LSP_MAX_BUFFER_BYTES = 16 * 1024 * 1024;
9	const EDIT_DIAGNOSTICS_GRACE_MS = 8_000;
10	const LSP_TOOLCHAIN_VARS = ["RUSTUP_HOME", "CARGO_HOME", "RUSTUP_TOOLCHAIN", "GOPATH", "GOROOT", "GOCACHE", "GOMODCACHE"];
11	
12	const SYSTEM_BIN_DIRS = ["/usr/bin", "/bin", "/usr/local/bin", "/sbin", "/usr/sbin"];
13	
14	function realOrNull(p: string): string | null {
15	  try {
16	    return fs.realpathSync(p);
17	  } catch {
18	    return null;
19	  }
20	}
21	
22	const isInside = (parent: string, child: string): boolean => {
23	  const rel = path.relative(parent, child);
24	  return rel === "" || (rel !== ".." && !rel.startsWith(".." + path.sep) && !path.isAbsolute(rel));
25	};
26	
27	/**
28	 * The environment a language server starts with: the MCP allowlist (no credentials) plus the toolchain locations the
29	 * servers need. PATH keeps only existing absolute entries that do not resolve (through symlinks) into the workspace, so
30	 * project content cannot supply the binary. When the workspace is a home directory or a system prefix that itself
31	 * contains the toolchain, its entries are kept: dropping them would leave no server installed.
32	 */
33	export function buildLspEnvironment(workspace: string, source: NodeJS.ProcessEnv = process.env): Record<string, string> {
34	  const env = buildMcpEnvironment();
35	  for (const k of LSP_TOOLCHAIN_VARS) if (source[k] !== undefined) env[k] = source[k]!;
36	  for (const [k, v] of Object.entries(env)) {
37	    if (/^(https?|all)_proxy$/i.test(k) && /\/\/[^/]*@/.test(v)) delete env[k];
38	  }
39	  const root = realOrNull(path.resolve(workspace));
40	  const broad =
41	    root !== null &&
42	    [os.homedir(), ...SYSTEM_BIN_DIRS].some((d) => {
43	      const real = realOrNull(d);
44	      return real !== null && isInside(root, real);
45	    });
46	  env.PATH = (env.PATH ?? "")
47	    .split(path.delimiter)
48	    .filter((d) => {
49	      if (!path.isAbsolute(d) || root === null) return false;
50	      const real = realOrNull(d);
51	      return real !== null && (broad || !isInside(root, real));
52	    })
53	    .join(path.delimiter);
54	  return env;
55	}
