57	export interface LspPosition {
58	  line: number;
59	  character: number;
60	}
61	
62	export interface LspRange {
63	  start: LspPosition;
64	  end: LspPosition;
65	}
66	
67	export interface LspLocation {
68	  uri: string;
69	  range: LspRange;
70	}
71	
72	export interface LspServerSpec {
73	  cmd: string;
74	  args?: string[];
75	  languageId: string;
76	  /** Extra variables for this server only; the built-in table never sets it. */
77	  env?: Record<string, string>;
78	  /**
79	   * The server analyses in stages and publishes an empty list before it has finished (rust-analyzer: before the Cargo
80	   * project is loaded and types are analysed). Diagnostics then wait, within the caller's timeout, until the server's own
81	   * progress reports (`$/progress`) have ended, instead of returning on the first publish.
82	   */
83	  awaitProgress?: boolean;
84	}
85	
86	export interface LspDiagnostic {
87	  range: LspRange;
88	  severity: "error" | "warning" | "information" | "hint";
89	  message: string;
90	  source?: string;
91	  code?: string | number;
92	}
