94	/**
95	 * Lightweight Language Server Protocol Client (Candidate #44)
96	 * Communicates with rust-analyzer, typescript-language-server, pyright via JSON-RPC stdio
97	 */
98	export class LspClient {
99	  public serverCmd: string;
100	  public serverArgs: string[];
101	  public rootPath: string;
102	  private opened: Map<string, { version: number; text: string }> = new Map();
103	  private diagnosticWaiters: Map<string, Array<() => void>> = new Map();
104	  private child: ChildProcess | null = null;
105	  private nextId: number = 1;
106	  private pending: Map<number, { resolve: (val: any) => void; reject: (err: any) => void }> = new Map();
107	  private diagnosticsMap: Map<string, LspDiagnostic[]> = new Map();
108	  private documentChangedAt: Map<string, number> = new Map();
109	  private saveOptions?: { includeText?: boolean };
110	  private buffer: Buffer = Buffer.alloc(0);
111	  public initialized: boolean = false;
112	  /** Tokens of the server's work-done progress that has begun and not ended, and when progress last changed. */
113	  private progressActive: Set<string> = new Set();
114	  private progressSeen = false;
115	  private lastProgressAt = 0;
116	
117	  constructor(serverCmd: string, rootPath: string, serverArgs: string[] = [], private extraEnv: Record<string, string> = {}, private awaitProgress: boolean = false) {
118	    this.serverCmd = serverCmd;
119	    this.serverArgs = serverArgs;
120	    this.rootPath = path.resolve(rootPath);
121	  }
122	
123	  public async start(): Promise<boolean> {
124	    try {
125	      this.child = spawn(this.serverCmd, this.serverArgs, {
126	        cwd: this.rootPath,
127	        env: { ...buildLspEnvironment(this.rootPath), ...this.extraEnv },
128	        stdio: ["pipe", "pipe", "pipe"],
129	      });
130	      this.child.stderr?.resume();
131	
132	      this.child.on("error", () => {
133	        this.initialized = false;
134	      });
135	
136	      this.child.on("exit", () => {
137	        this.initialized = false;
138	        this.failInFlight(new Error(`LSP server '${this.serverCmd}' exited`));
139	      });
140	      this.child.stdin?.on("error", () => {
141	        this.initialized = false;
142	      });
143	
144	      this.child.stdout?.on("data", (data: Buffer) => {
145	        this.handleData(data);
146	      });
147	
148	      const rootUri = pathToFileURL(this.rootPath).href;
149	
150	      // 1. Initialize
151	      const initRes = await this.sendRequest("initialize", {
152	        processId: process.pid,
153	        rootUri,
154	        capabilities: {
155	          textDocument: {
156	            hover: { contentFormat: ["markdown", "plaintext"] },
157	            definition: { dynamicRegistration: true },
158	            // Ask servers to attach document versions so delayed results for pre-edit content can be rejected.
159	            publishDiagnostics: { relatedInformation: true, versionSupport: true },
160	            synchronization: { didSave: true },
161	          },
162	          // Declared so that servers which report progress (rust-analyzer) send $/progress, which diagnostics wait on.
163	          window: { workDoneProgress: true },
164	        },
165	      }, 5000);
166	
167	      if (!initRes) return false;
168	      const sync = initRes.capabilities?.textDocumentSync;
169	      if (typeof sync === "object" && sync?.save) {
170	        this.saveOptions = typeof sync.save === "object" ? sync.save : {};
171	      }
172	
173	      // 2. Initialized notification
174	      this.sendNotification("initialized", {});
175	      this.initialized = true;
176	      return true;
177	    } catch {
178	      this.initialized = false;
179	      return false;
180	    }
181	  }
182	
183	  /** Rejects every request still waiting and wakes every diagnostics waiter: the server is gone, so no answer is coming. */
184	  private failInFlight(err: Error): void {
185	    for (const { reject } of this.pending.values()) reject(err);
186	    this.pending.clear();
187	    const waiters = [...this.diagnosticWaiters.values()].flat();
188	    this.diagnosticWaiters.clear();
189	    for (const w of waiters) w();
190	  }
191	
192	  /** A server that sends more than the cap in one message, or buffers past it, is dropped rather than trusted with memory. */
193	  private dropOversized(): void {
194	    this.buffer = Buffer.alloc(0);
195	    this.initialized = false;
196	    this.failInFlight(new Error(`LSP server '${this.serverCmd}' exceeded the ${LSP_MAX_BUFFER_BYTES}-byte message limit`));
197	    try {
198	      this.child?.kill("SIGKILL");
199	    } catch {}
200	  }
201	
202	  private handleData(chunk: Buffer): void {
203	    this.buffer = Buffer.concat([this.buffer, chunk]);
204	
205	    while (true) {
206	      const headerEnd = this.buffer.indexOf("\r\n\r\n");
207	      if (headerEnd === -1) break;
208	
209	      const header = this.buffer.subarray(0, headerEnd).toString("latin1");
210	      const match = header.match(/Content-Length:\s*(\d+)/i);
211	      if (!match) {
212	        this.buffer = this.buffer.subarray(headerEnd + 4);
213	        continue;
214	      }
215	
216	      const contentLength = parseInt(match[1], 10);
217	      if (contentLength > LSP_MAX_BUFFER_BYTES) return this.dropOversized();
218	      const bodyStart = headerEnd + 4;
219	
220	      if (this.buffer.length < bodyStart + contentLength) {
221	        // Incomplete body, wait for next chunk
222	        break;
223	      }
224	
225	      const body = this.buffer.subarray(bodyStart, bodyStart + contentLength).toString("utf-8");
226	      this.buffer = this.buffer.subarray(bodyStart + contentLength);
227	
228	      try {
229	        const msg = JSON.parse(body);
230	        if (typeof msg.method === "string" && msg.id !== undefined) {
231	          // A request FROM the server (it has a method; its id space is its own, so it can collide with ours): answer it, or
232	          // a server that waits for the reply (window/workDoneProgress/create, workspace/configuration) can stall.
233	          this.answerServerRequest(msg);
234	          continue;
235	        }
236	        if (msg.method === "$/progress" && msg.params) {
237	          const token = String(msg.params.token);
238	          const kind = msg.params.value?.kind;
239	          if (kind === "begin") this.progressActive.add(token);
240	          else if (kind === "end") this.progressActive.delete(token);
241	          this.progressSeen = true;
242	          this.lastProgressAt = Date.now();
243	          continue;
244	        }
245	        if (msg.id !== undefined && this.pending.has(msg.id)) {
246	          const { resolve, reject } = this.pending.get(msg.id)!;
247	          this.pending.delete(msg.id);
248	          if (msg.error) {
249	            reject(new Error(msg.error.message || JSON.stringify(msg.error)));
250	          } else {
251	            resolve(msg.result);
252	          }
253	        } else if (msg.method === "textDocument/publishDiagnostics") {
254	          const params = msg.params;
255	          if (params && params.uri && Array.isArray(params.diagnostics)) {
256	            const diags: LspDiagnostic[] = params.diagnostics.map((d: any) => ({
257	              range: d.range,
258	              severity: d.severity === 1 ? "error" : d.severity === 2 ? "warning" : "information",
259	              message: d.message,
260	              source: d.source,
261	              ...(d.code !== undefined && d.code !== null ? { code: d.code } : {}),
262	            }));
263	            const current = this.opened.get(params.uri);
264	            if (typeof params.version === "number" && current && params.version !== current.version) {
265	              continue; // published for an older version of the file than the server was last told about
266	            }
267	            this.diagnosticsMap.set(params.uri, diags);
268	            const waiters = this.diagnosticWaiters.get(params.uri);
269	            if (waiters) {
270	              this.diagnosticWaiters.delete(params.uri);
271	              for (const w of waiters) w();
272	            }
273	          }
274	        }
275	      } catch {}
276	    }
277	    if (this.buffer.length > LSP_MAX_BUFFER_BYTES + 1024) this.dropOversized();
278	  }
279	
280	  public async sendRequest(method: string, params: any, timeoutMs: number = 8000): Promise<any> {
281	    if (!this.child || !this.child.stdin || this.child.killed || this.child.exitCode !== null) {
282	      throw new Error(`LSP server '${this.serverCmd}' is not running`);
283	    }
284	
285	    const id = this.nextId++;
286	    const payload = JSON.stringify({
287	      jsonrpc: "2.0",
288	      id,
289	      method,
290	      params,
291	    });
292	
293	    const header = `Content-Length: ${Buffer.byteLength(payload, "utf-8")}\r\n\r\n`;
294	
295	    return new Promise((resolve, reject) => {
296	      const timer = setTimeout(() => {
297	        if (this.pending.has(id)) {
298	          this.pending.delete(id);
299	          reject(new Error(`LSP request '${method}' timed out after ${timeoutMs}ms`));
300	        }
301	      }, timeoutMs);
302	
303	      this.pending.set(id, {
304	        resolve: (val) => {
305	          clearTimeout(timer);
306	          resolve(val);
307	        },
308	        reject: (err) => {
309	          clearTimeout(timer);
310	          reject(err);
311	        },
312	      });
313	
314	      this.child!.stdin!.write(header + payload);
315	    });
316	  }
317	
318	  private answerServerRequest(msg: { id: number | string; method: string; params?: any }): void {
319	    if (!this.child || !this.child.stdin || this.child.killed || this.child.exitCode !== null) return;
320	    // Nothing is configured or registered on the server's behalf: an empty answer is a valid one for the requests servers send.
321	    const result = msg.method === "workspace/configuration" && Array.isArray(msg.params?.items) ? msg.params.items.map(() => null) : null;
322	    const payload = JSON.stringify({ jsonrpc: "2.0", id: msg.id, result });
323	    this.child.stdin.write(`Content-Length: ${Buffer.byteLength(payload, "utf-8")}\r\n\r\n${payload}`);
324	  }
325	
326	  public sendNotification(method: string, params: any): void {
327	    if (!this.child || !this.child.stdin || this.child.killed || this.child.exitCode !== null) return;
328	    const payload = JSON.stringify({
329	      jsonrpc: "2.0",
330	      method,
331	      params,
332	    });
333	    const header = `Content-Length: ${Buffer.byteLength(payload, "utf-8")}\r\n\r\n`;
334	    this.child.stdin.write(header + payload);
335	  }
336	
337	  public notifyFileOpen(filePath: string, content: string, languageId: string): void {
338	    const uri = pathToFileURL(path.resolve(this.rootPath, filePath)).href;
339	    this.sendNotification("textDocument/didOpen", {
340	      textDocument: {
341	        uri,
342	        languageId,
343	        version: 1,
344	        text: content,
345	      },
346	    });
347	  }
348	
349	  /**
350	   * Makes the server's view of the file match the disk: didOpen the first time, a full-text didChange when the content
351	   * moved since. Diagnostics for a changed file are dropped so a caller waits for fresh ones, never a stale list.
352	   * Returns false when the file cannot be read or lies outside the workspace.
353	   */
354	  public syncFile(filePath: string, languageId: string): boolean {
355	    let abs: string;
356	    let text: string;
357	    try {
358	      // Resolve symlinks before the containment check: a link inside the workspace must not read a file outside it.
359	      abs = fs.realpathSync(path.resolve(this.rootPath, filePath));
360	      const root = fs.realpathSync(this.rootPath);
361	      const rel = path.relative(root, abs);
362	      if (rel.startsWith("..") || path.isAbsolute(rel)) return false;
363	      text = fs.readFileSync(abs, "utf-8");
364	    } catch {
365	      return false;
366	    }
367	    const uri = pathToFileURL(path.resolve(this.rootPath, filePath)).href;
368	    const prev = this.opened.get(uri);
369	    if (!prev) {
370	      this.opened.set(uri, { version: 1, text });
371	      this.sendNotification("textDocument/didOpen", { textDocument: { uri, languageId, version: 1, text } });
372	    } else if (prev.text !== text) {
373	      const version = prev.version + 1;
374	      this.opened.set(uri, { version, text });
375	      this.diagnosticsMap.delete(uri);
376	      this.documentChangedAt.set(uri, Date.now());
377	      // Startup progress does not mean work for this newer document version has settled. A server may first
378	      // publish diagnostics for the updated version before its analysis has caught up; make the bounded grace
379	      // path apply again unless this edit produces fresh progress notifications.
380	      this.progressSeen = false;
381	      this.lastProgressAt = 0;
382	      this.sendNotification("textDocument/didChange", {
383	        textDocument: { uri, version },
384	        contentChanges: [{ text }],
385	      });
386	      if (this.saveOptions) {
387	        this.sendNotification("textDocument/didSave", {
388	          textDocument: { uri },
389	          ...(this.saveOptions.includeText ? { text } : {}),
390	        });
391	      }
392	    }
393	    return true;
394	  }
395	
396	  /** Resolves with the diagnostics the server published for the file, or null if none arrived within the timeout. */
397	  public async waitForDiagnostics(filePath: string, timeoutMs: number): Promise<LspDiagnostic[] | null> {
398	    const uri = pathToFileURL(path.resolve(this.rootPath, filePath)).href;
399	    const startedAt = Date.now();
400	    const changedAt = this.documentChangedAt.get(uri);
401	    const first = await this.firstDiagnostics(uri, timeoutMs);
402	    if (!this.awaitProgress || !first) return first;
403	    // A staged server's first publish may be empty. Wait until its progress has ended and been quiet for a moment (or, if it
404	    // never reports progress, for a grace period), within the caller's timeout, then return the latest list.
405	    const QUIET_MS = 1500;
406	    const GRACE_MS = 4000;
407	    while (Date.now() - startedAt < timeoutMs) {
408	      const now = Date.now();
409	      const idle = this.progressActive.size === 0;
410	      const settled = this.progressSeen ? now - this.lastProgressAt >= QUIET_MS : now - startedAt >= GRACE_MS;
411	      const editSettled = changedAt === undefined || now - changedAt >= EDIT_DIAGNOSTICS_GRACE_MS;
412	      if (idle && settled && editSettled) break;
413	      await new Promise((r) => setTimeout(r, 100));
414	    }
415	    if (changedAt !== undefined && Date.now() - changedAt >= EDIT_DIAGNOSTICS_GRACE_MS) this.documentChangedAt.delete(uri);
416	    return this.diagnosticsMap.get(uri) ?? first;
417	  }
418	
419	  private async firstDiagnostics(uri: string, timeoutMs: number): Promise<LspDiagnostic[] | null> {
420	    const have = this.diagnosticsMap.get(uri);
421	    if (have) return have;
422	    await new Promise<void>((resolve) => {
423	      const timer = setTimeout(() => {
424	        const list = this.diagnosticWaiters.get(uri)?.filter((w) => w !== done) ?? [];
425	        if (list.length) this.diagnosticWaiters.set(uri, list);
426	        else this.diagnosticWaiters.delete(uri);
427	        resolve();
428	      }, timeoutMs);
429	      const done = () => {
430	        clearTimeout(timer);
431	        resolve();
432	      };
433	      this.diagnosticWaiters.set(uri, [...(this.diagnosticWaiters.get(uri) ?? []), done]);
434	    });
435	    return this.diagnosticsMap.get(uri) ?? null;
436	  }
437	
438	  public pid(): number | undefined {
439	    return this.child?.pid;
440	  }
441	
442	  public async getHover(filePath: string, line: number, character: number): Promise<string | null> {
443	    const uri = pathToFileURL(path.resolve(this.rootPath, filePath)).href;
444	    const res = await this.sendRequest("textDocument/hover", {
445	      textDocument: { uri },
446	      position: { line: Math.max(0, line - 1), character: Math.max(0, character - 1) },
447	    });
448	
449	    if (!res || !res.contents) return null;
450	
451	    if (typeof res.contents === "string") return res.contents;
452	    if (res.contents.value) return res.contents.value;
453	    if (Array.isArray(res.contents)) {
454	      return res.contents.map((c: any) => (typeof c === "string" ? c : c.value || "")).join("\n\n");
455	    }
456	    return JSON.stringify(res.contents);
457	  }
458	
459	  public async getDefinition(filePath: string, line: number, character: number): Promise<LspLocation[] | null> {
460	    const uri = pathToFileURL(path.resolve(this.rootPath, filePath)).href;
461	    const res = await this.sendRequest("textDocument/definition", {
462	      textDocument: { uri },
463	      position: { line: Math.max(0, line - 1), character: Math.max(0, character - 1) },
464	    });
465	
466	    if (!res) return null;
467	    if (Array.isArray(res)) return res;
468	    if (res.uri && res.range) return [res];
469	    return null;
470	  }
471	
472	  /** null means the server never published for this file: no data, which is not the same as no errors. */
473	  public getDiagnostics(filePath: string): LspDiagnostic[] | null {
474	    const uri = pathToFileURL(path.resolve(this.rootPath, filePath)).href;
475	    return this.diagnosticsMap.get(uri) ?? null;
476	  }
477	
478	  public shutdown(): void {
479	    if (this.child) {
480	      try {
481	        this.sendRequest("shutdown", {}).catch(() => {});
482	        this.sendNotification("exit", {});
483	        this.child.kill("SIGTERM");
484	      } catch {}
485	      this.child = null;
486	    }
487	    this.initialized = false;
488	  }
489	}
