491	/**
492	 * Manager to auto-route LSP queries based on file extension
493	 */
494	export class LspBridgeManager {
495	  private static live: Set<LspBridgeManager> = new Set();
496	  private static exitHookInstalled = false;
497	
498	  private workspace: string;
499	  private clients: Map<string, LspClient> = new Map();
500	  private starting: Map<string, Promise<LspClient | null>> = new Map();
501	  private closed = false;
502	  private servers: Record<string, LspServerSpec>;
503	  private gate?: () => string | null;
504	
505	  /** `gate` returns the reason a server must not start right now (untrusted workspace, sandbox), or null to allow it. */
506	  constructor(workspace: string, opts: { servers?: Record<string, LspServerSpec>; gate?: () => string | null } = {}) {
507	    this.workspace = path.resolve(workspace);
508	    this.gate = opts.gate;
509	    this.servers = opts.servers ?? {};
510	    LspBridgeManager.live.add(this);
511	    if (!LspBridgeManager.exitHookInstalled) {
512	      LspBridgeManager.exitHookInstalled = true;
513	      // Backstop: a language server must never outlive the process, even if no owner called shutdownAll.
514	      process.on("exit", () => {
515	        for (const m of LspBridgeManager.live) m.shutdownAll();
516	      });
517	    }
518	  }
519	
520	  /** The gate's refusal, if any. A refusal also stops servers that started while the workspace was still allowed. */
521	  private refusal(): string | null {
522	    const reason = this.gate?.() ?? null;
523	    if (reason) {
524	      for (const client of this.clients.values()) client.shutdown();
525	      this.clients.clear();
526	    }
527	    return reason;
528	  }
529	
530	  public getServerForFile(filePath: string): LspServerSpec | null {
531	    const ext = path.extname(filePath).toLowerCase();
532	    if (this.servers[ext]) return this.servers[ext];
533	    if (ext === ".rs") {
534	      return { cmd: "rust-analyzer", languageId: "rust", awaitProgress: true };
535	    }
536	    if (ext === ".ts" || ext === ".tsx") {
537	      return { cmd: "typescript-language-server", args: ["--stdio"], languageId: "typescript" };
538	    }
539	    if (ext === ".js" || ext === ".jsx") {
540	      return { cmd: "typescript-language-server", args: ["--stdio"], languageId: "javascript" };
541	    }
542	    if (ext === ".py") {
543	      return { cmd: "pyright-langserver", args: ["--stdio"], languageId: "python" };
544	    }
545	    if (ext === ".go") {
546	      return { cmd: "gopls", languageId: "go" };
547	    }
548	    return null;
549	  }
550	
551	  public async getClientForFile(filePath: string): Promise<LspClient | null> {
552	    const serverInfo = this.getServerForFile(filePath);
553	    if (!serverInfo || this.refusal()) return null;
554	    this.closed = false;
555	    LspBridgeManager.live.add(this);
