        "lsp_hover",
        "lsp_definition",
        "lsp_diagnostics",
        "run_tests",
      ].includes(cap.modelToolName)
    ) {
      registry.setHandler(cap.modelToolName, async (args, context) =>
        bridge.executeTool(cap.modelToolName, args, context?.metadata?.verificationAuthority)
      );
    }
  }
