    {
      "$schema": "https://opencode.ai/config.json",
      "lsp": {
        "custom-lsp": {
          "command": ["custom-lsp-server", "--stdio"],
          "extensions": [".custom"],
          "initialization": {
            "preferences": {
              "importModuleSpecifierPreference": "relative"
            }
          }
        }
      }
    }
    ```

